class Solution {
public:
    int closetTarget(std::vector<std::string>& words, std::string target, int startIndex) {
        int n = words.size();
        int ans = 1e9;
        for (int i = 0; i < n; ++i) {
            if (words[i] == target) {
                int diff = std::abs(i - startIndex);
                ans = std::min(ans, std::min(diff, n - diff));
            }
        }
        return ans == 1e9 ? -1 : ans;
    }
};

class Solution {
    public int closetTarget(String[] words, String target, int startIndex) {
        int n = words.length;
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (words[i].equals(target)) {
                int diff = Math.abs(i - startIndex);
                ans = Math.min(ans, Math.min(diff, n - diff));
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

var closetTarget = function(words, target, startIndex) {
    const n = words.length;
    let ans = Infinity;
    for (let i = 0; i < n; i++) {
        if (words[i] === target) {
            const diff = Math.abs(i - startIndex);
            const dist = Math.min(diff, n - diff);
            if (dist < ans) ans = dist;
        }
    }
    return ans === Infinity ? -1 : ans;
};
